package com.lbos.commercecustomer.exception; import com.lbos.commercecustomer.dto.response.*;import jakarta.servlet.http.HttpServletRequest;import java.time.OffsetDateTime;import java.util.*;import org.springframework.dao.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class GlobalExceptionHandler {private ErrorResponse errorBody(HttpStatus status,String code,String category,String title,String userMessage,List<FieldErrorResponse> fieldErrors,HttpServletRequest request,boolean retry){return new ErrorResponse(OffsetDateTime.now(),status.value(),code,category,title,userMessage,fieldErrors,request.getRequestURI(),Optional.ofNullable(request.getHeader("X-Correlation-Id")).orElse("not-provided"),retry);}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException exception,HttpServletRequest r){var fieldErrors=exception.getBindingResult().getFieldErrors().stream().map(fieldError->new FieldErrorResponse(fieldError.getField(),fieldError.getRejectedValue(),fieldError.getDefaultMessage(),"INVALID_FIELD")).toList();return ResponseEntity.badRequest().body(errorBody(HttpStatus.BAD_REQUEST,"INVALID_REQUEST","VALIDATION","Validation failed","Correct the highlighted fields",fieldErrors,r,false));}@ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<ErrorResponse> malformed(HttpMessageNotReadableException exception,HttpServletRequest r){return ResponseEntity.badRequest().body(errorBody(HttpStatus.BAD_REQUEST,"MALFORMED_REQUEST_BODY","VALIDATION","The request body could not be parsed - check enum values and field types match the API contract","The request could not be understood",List.of(),r,false));}@ExceptionHandler(MissingAuthenticatedUserException.class) ResponseEntity<ErrorResponse> missing(RuntimeException exception,HttpServletRequest r){return ResponseEntity.status(401).body(errorBody(HttpStatus.UNAUTHORIZED,"MISSING_AUTHENTICATED_USER","AUTHENTICATION",exception.getMessage(),"Authentication context is missing",List.of(),r,false));}@ExceptionHandler(InvalidAuthenticatedUserException.class) ResponseEntity<ErrorResponse> invalid(RuntimeException exception,HttpServletRequest r){return ResponseEntity.badRequest().body(errorBody(HttpStatus.BAD_REQUEST,"INVALID_AUTHENTICATED_USER","VALIDATION",exception.getMessage(),"Authentication context is invalid",List.of(),r,false));}@ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ErrorResponse> notFound(RuntimeException exception,HttpServletRequest r){return ResponseEntity.status(404).body(errorBody(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","NOT_FOUND",exception.getMessage(),"The requested resource was not found",List.of(),r,false));}@ExceptionHandler({DuplicateResourceException.class,DataIntegrityViolationException.class}) ResponseEntity<ErrorResponse> conflict(Exception exception,HttpServletRequest r){String technicalMessage=exception instanceof DataIntegrityViolationException?"A database constraint was violated":exception.getMessage();return ResponseEntity.status(409).body(errorBody(HttpStatus.CONFLICT,"RESOURCE_CONFLICT","CONFLICT",technicalMessage,"The request conflicts with existing data",List.of(),r,false));}@ExceptionHandler({BusinessValidationException.class,InsufficientStockException.class}) ResponseEntity<ErrorResponse> business(RuntimeException exception,HttpServletRequest r){return ResponseEntity.unprocessableEntity().body(errorBody(HttpStatus.UNPROCESSABLE_ENTITY,"BUSINESS_RULE_VIOLATION","BUSINESS_RULE",exception.getMessage(),exception.getMessage(),List.of(),r,false));}@ExceptionHandler(ForbiddenOperationException.class) ResponseEntity<ErrorResponse> forbidden(RuntimeException exception,HttpServletRequest r){return ResponseEntity.status(403).body(errorBody(HttpStatus.FORBIDDEN,"FORBIDDEN_OPERATION","AUTHORIZATION",exception.getMessage(),"The operation is not permitted",List.of(),r,false));}@ExceptionHandler(ExternalServiceUnavailableException.class) ResponseEntity<ErrorResponse> unavailable(RuntimeException exception,HttpServletRequest r){return ResponseEntity.status(503).body(errorBody(HttpStatus.SERVICE_UNAVAILABLE,"DEPENDENCY_UNAVAILABLE","EXTERNAL_DEPENDENCY",exception.getMessage(),"A required service is unavailable",List.of(),r,true));}@ExceptionHandler(ExternalServiceTimeoutException.class) ResponseEntity<ErrorResponse> timeout(RuntimeException exception,HttpServletRequest r){return ResponseEntity.status(504).body(errorBody(HttpStatus.GATEWAY_TIMEOUT,"DEPENDENCY_TIMEOUT","TIMEOUT",exception.getMessage(),"A required service timed out",List.of(),r,true));}@ExceptionHandler(org.springframework.web.multipart.MaxUploadSizeExceededException.class) ResponseEntity<ErrorResponse> tooLarge(Exception exception,HttpServletRequest r){return ResponseEntity.status(413).body(errorBody(HttpStatus.PAYLOAD_TOO_LARGE,"FILE_TOO_LARGE","VALIDATION","File too large","The file is too large. Upload a smaller file.",List.of(),r,false));}@ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> generic(Exception exception,HttpServletRequest r){return ResponseEntity.internalServerError().body(errorBody(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_SERVER_ERROR","INTERNAL","Unexpected error","The request could not be completed",List.of(),r,false));}}